// The count table in `docs/architecture.md` is written from the archive rather
// than by hand, so a pull request that adds a record or a redrawing resolves a
// conflict on it by running one command instead of counting (#520).
//
// `npm run docs:counts` rewrites the tables between the two markers, one per
// series in `src/data/series/index.ts`, under its slug.
// `npm run gate:docs` (`--check`) writes nothing and fails when the committed
// table differs from what the script would write. The output goes through
// Prettier, so `format:check` passes on a freshly generated file.
import { readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { pathToFileURL } from 'node:url'
import { format, resolveConfig } from 'prettier'

import { importArchive, ROOT } from './archive-loader.mjs'

/** The document the table sits in. */
// fallow-ignore-next-line security-sink -- a constant: the repository's own docs folder
export const DOC_PATH = path.join(ROOT, 'docs', 'architecture.md')

const BEGIN =
  '<!-- Generated by `npm run docs:counts` from the archive. Do not edit by hand. -->'
const END = '<!-- End of the generated counts. -->'

/**
 * The document with the text between the markers replaced by the table.
 * @param {string} document The document as it sits on disk.
 * @param {string} table The table, without a trailing newline.
 * @returns {string} The document with the new table.
 */
export function withTable(document, table) {
  const start = document.indexOf(BEGIN)
  const end = document.indexOf(END)

  if (start === -1 || end < start) {
    throw new Error(
      'docs/architecture.md has lost the markers around the counts table.',
    )
  }

  return `${document.slice(0, start + BEGIN.length)}\n\n${table}\n\n${document.slice(end)}`
}

/**
 * One series' table, counted from its archive.
 * @param {{ archive: { drawings: Record<string, unknown>, entities: { kind: string }[], sagas: unknown[], timelines: { field: string, timeline: unknown[] }[] } }} series The series, from the list.
 * @returns {string} The markdown table, not yet padded.
 */
export function countTable({ archive }) {
  const { drawings, entities, sagas, timelines } = archive
  const ofKind = (kind) =>
    entities.filter((entity) => entity.kind === kind).length
  const filed = (field) =>
    timelines
      .filter((owned) => owned.field === field)
      .map(({ timeline }) => timeline)
      .filter((timeline) => timeline.length > 0)
  const redrawings = filed('redrawing')
  const chronicles = filed('chronicle')

  const rows = [
    ['Records', entities.length],
    ['Characters', ofKind('character')],
    ['Devil fruits', ofKind('fruit')],
    [
      'Arcs, places, ships',
      `${ofKind('arc')} · ${ofKind('place')} · ${ofKind('ship')}`,
    ],
    ['Saga modules', `${sagas.length}, plus one for the devil fruits`],
    [
      'Line drawings',
      `${Object.keys(drawings).length}, one per record, plus ${redrawings.flat().length} redrawings of ${redrawings.length} records`,
    ],
    [
      'Chronicle stories',
      `${chronicles.flat().length}, for ${chronicles.length} characters`,
    ],
  ]

  return [
    '| Thing | Count |',
    '| --- | --- |',
    ...rows.map(([thing, count]) => `| ${thing} | ${count} |`),
  ].join('\n')
}

/**
 * Every series' table under its slug, in the order of the list.
 * @returns {Promise<string>} The markdown, not yet padded.
 */
async function countTables() {
  const { SERIES } = await importArchive('data/series/index.ts')

  return SERIES.map(
    (series) => `### \`${series.slug}\`\n\n${countTable(series)}`,
  ).join('\n\n')
}

/**
 * The document as it is, and as the script would write it.
 * @returns {Promise<{after: string, before: string}>} Both texts.
 */
async function render() {
  const before = readFileSync(DOC_PATH, 'utf8')
  const options = await resolveConfig(DOC_PATH)
  const after = await format(withTable(before, await countTables()), {
    ...options,
    filepath: DOC_PATH,
  })

  return { after, before }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const { after, before } = await render()

  if (process.argv.includes('--check')) {
    if (after === before) {
      console.log('docs/architecture.md: the counts table is up to date.')
    } else {
      console.error(
        'docs/architecture.md: the counts table is stale: run npm run docs:counts',
      )
      process.exitCode = 1
    }
  } else {
    writeFileSync(DOC_PATH, after)
    console.log(
      after === before ?
        'docs/architecture.md is already up to date.'
      : 'docs/architecture.md: the counts table rewritten.',
    )
  }
}
